#!/usr/bin/env bash
# =============================================================================
#  Maskfish / Jieqi NNUE — full training pipeline for one "generation"
#
#  build engine → bit-exact check → (gen0 net) → generate train + val data
#  → fit scaling → prepare → train → verify exported net → SPRT → promote
#
#  Sends a Telegram ✅ after every step; on error sends ❌ at once with the
#  tail of the log, then stops.
#
#  Generation numbering (as in trainer/README.md):
#     -g N : nets/genN.nnue is the CURRENT net
#            data/genN.txt, data/valN.txt are generated by that net
#            train on data 0..N  →  runs/gen(N+1)/  →  nets/gen(N+1).nnue
#
#  Examples:
#     scripts/pipeline.sh -g 0              # full run gen 0 → gen1
#     scripts/pipeline.sh -g 1 --gen-only   # only generate data (+prepare) with nets/gen1.nnue
#     scripts/pipeline.sh -g 1 --train-only # only train/verify/SPRT on existing data
#     scripts/pipeline.sh -g 1 --gen-only --tag m2 --no-prepare   # second helper machine
#     scripts/pipeline.sh --test-telegram
#
#  Config: trainer/scripts/pipeline.env (copy of pipeline.env.example) or --config.
#  Hardware parameters left empty are chosen for the machine (hw_probe.py):
#  workers from CPU/RAM, shard size from RAM, batch size by a trial run on the
#  GPU, checkpoint interval from free disk space.
# =============================================================================
set -uo pipefail
if (( BASH_VERSINFO[0] < 4 || (BASH_VERSINFO[0] == 4 && BASH_VERSINFO[1] < 4) )); then
  echo "bash >= 4.4 required (this is $BASH_VERSION)" >&2; exit 2
fi

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"      # trainer/scripts
TRAINER_DIR="$(cd "$SCRIPT_DIR/.." && pwd)"                     # trainer
cd "$TRAINER_DIR" || exit 1          # the trainer scripts, data/, nets/, runs/, logs/ live here
SRC_DIR="$(cd "$TRAINER_DIR/../src" && pwd)"

# ----------------------------------------------------------------------------- CLI
usage() { sed -n '2,27p' "$0" | sed 's/^# \{0,1\}//'; cat <<'EOF'
Options:
  -g, --gen N          Generation number of the current net (required, except --test-telegram)
      --gen-only       Only: build, init gen0 net (if N=0), generate train+val data, prepare
      --train-only     Only: checks, prepare what is missing, train, verify, SPRT, promote
      --no-prepare     (with --gen-only) do not prepare — for helper machines that only write text
      --tag NAME       Machine / data batch name (file data/genN_NAME.txt), for several machines
      --config FILE    Config file (default: scripts/pipeline.env if present)
      --skip-check     Skip the initial verify.py engine/trainer bit-exact check
      --skip-match     Skip SPRT (and promote)
      --rebuild        Rebuild the engine even if the binary exists
      --no-resume      Do not --resume automatically from runs/.../last.pt
      --force          Regenerate / re-prepare data even if present (DELETES this tag's old shards)
      --dry-run        Only print the commands; run nothing, send no real Telegram message
      --test-telegram  Send a test message and exit
  -h, --help
EOF
}

GEN=""; MODE="full"; TAG=""; CONFIG=""; NO_PREPARE=0; SKIP_CHECK=0; SKIP_MATCH=0
REBUILD=0; NO_RESUME=0; FORCE=0; DRY_RUN=0; TEST_TG=0
while [[ $# -gt 0 ]]; do
  case "$1" in
    -g|--gen)        GEN="${2:-}"; shift 2 ;;
    --gen-only)      MODE="gen"; shift ;;
    --train-only)    MODE="train"; shift ;;
    --no-prepare)    NO_PREPARE=1; shift ;;
    --tag)           TAG="${2:-}"; shift 2 ;;
    --config)        CONFIG="${2:-}"; shift 2 ;;
    --skip-check)    SKIP_CHECK=1; shift ;;
    --skip-match)    SKIP_MATCH=1; shift ;;
    --rebuild)       REBUILD=1; shift ;;
    --no-resume)     NO_RESUME=1; shift ;;
    --force)         FORCE=1; shift ;;
    --dry-run)       DRY_RUN=1; shift ;;
    --test-telegram) TEST_TG=1; shift ;;
    -h|--help)       usage; exit 0 ;;
    *) echo "Unknown option: $1" >&2; usage >&2; exit 2 ;;
  esac
done

# ----------------------------------------------------------------------------- config
if [[ -z "$CONFIG" && -f "$SCRIPT_DIR/pipeline.env" ]]; then CONFIG="$SCRIPT_DIR/pipeline.env"; fi
if [[ -n "$CONFIG" ]]; then
  [[ -f "$CONFIG" ]] || { echo "Config file not found: $CONFIG" >&2; exit 2; }
  # shellcheck disable=SC1090
  source "$CONFIG"
fi

NCPU=$(nproc 2>/dev/null || getconf _NPROCESSORS_ONLN 2>/dev/null || echo 2)
# Hardware-dependent parameters: empty = chosen for the machine in the "Environment check" step
AUTO_VARS=(GEN_WORKERS MATCH_WORKERS PREP_WORKERS SHARD_SIZE BATCH_SIZE CHECKPOINT_EVERY TRAIN_THREADS)
declare -A USERSET=()
for _v in "${AUTO_VARS[@]}"; do [[ -n "${!_v:-}" ]] && USERSET[$_v]=1; done
if [[ -z "${PYTHON:-}" ]]; then
  if [[ -x "$TRAINER_DIR/.venv/bin/python" ]]; then PYTHON="$TRAINER_DIR/.venv/bin/python"; else PYTHON=python3; fi
fi
: "${TG_BOT_TOKEN:=}"; : "${TG_CHAT_ID:=}"; : "${TG_EPOCH_EVERY:=5}"; : "${TG_NAME:=$(hostname -s 2>/dev/null || hostname)}"
: "${MAKE_ARCH:=native}"; : "${NNUE_ARCH:=default}"; : "${LAYERS:=1}"
: "${META:=0}"; : "${BLEND:=0}"; : "${CTX:=0}"; : "${PSQT:=1}"; : "${QUANT:=1}"; : "${INIT_NET:=}"
: "${GAMES:=50000}"; : "${VAL_GAMES:=1000}"; : "${NODES:=5000}"; : "${DEPTH:=0}"
: "${GEN_WORKERS:=$(( NCPU > 1 ? NCPU - 1 : 1 ))}"; : "${ADJUDICATE:=3000}"; : "${GEN_OPTS:=}"
: "${CHANCE_SCALING:=}"; : "${SEED_BASE:=}"
: "${SHARD_SIZE:=2000000}"; : "${MAX_SCORE:=10000}"; : "${SCORE_SCALE:=1.0}"; : "${PREP_WORKERS:=}"
: "${EPOCHS:=40}"; : "${EPOCH_SIZE:=10000000}"; : "${BATCH_SIZE:=16384}"; : "${LR:=8.75e-4}"
: "${GAMMA:=0.992}"; : "${LAMBDA:=1.0}"; : "${SCALING:=361}"; : "${TRAIN_FROM:=0}"
: "${CHECKPOINT_EVERY:=1}"; : "${TRAIN_THREADS:=0}"; : "${BATCH_TARGET:=16384}"; : "${DEVICE:=}"; : "${REQUIRE_GPU:=1}"; : "${INIT_FROM_CURRENT:=1}"
: "${TRAIN_GPUS:=1}"; : "${QAT_START:=0}"; : "${FTPERM:=1}"; : "${EVAL_SCALING:=Complexity}"
case "$EVAL_SCALING" in
  Complexity|Alignment) ;;
  *) echo "EVAL_SCALING must be Complexity or Alignment" >&2; exit 2 ;;
esac
# The engine option EvalScaling and train.py --eval-scaling must agree (README 7.13)
EVAL_OPT=(); EVAL_ARG=()
if [[ "$EVAL_SCALING" == Alignment ]]; then EVAL_OPT=(EvalScaling=Alignment); EVAL_ARG=(--eval-scaling alignment); fi
: "${TRAIN_ARGS:=}"; : "${EXTRA_TRAIN:=}"
: "${MATCH_NODES:=20000}"; : "${MATCH_MOVETIME:=0}"; : "${MATCH_WORKERS:=$(( NCPU > 1 ? NCPU - 1 : 1 ))}"
: "${SPRT=0 5}"; : "${MATCH_EPOCHS:=last}"; : "${MATCH_OPTS:=}"; : "${AUTO_PROMOTE:=1}"

# ----------------------------------------------------------------------------- telegram
html_escape() { local s="$1"; s="${s//&/&amp;}"; s="${s//</&lt;}"; s="${s//>/&gt;}"; printf '%s' "$s"; }

tg_send() {   # $1 = text (already HTML-escaped where needed)
  local text="$1"
  (( ${#text} > 4000 )) && text="${text:0:3990}…"
  if (( DRY_RUN )); then echo "[telegram] $text"; return 0; fi
  [[ -z "$TG_BOT_TOKEN" || -z "$TG_CHAT_ID" ]] && return 0
  local resp
  resp=$(curl -sS --max-time 20 --retry 3 --retry-delay 3 \
          --data-urlencode "chat_id=${TG_CHAT_ID}" \
          --data-urlencode "text=${text}" \
          --data-urlencode "parse_mode=HTML" \
          --data-urlencode "disable_web_page_preview=true" \
          "https://api.telegram.org/bot${TG_BOT_TOKEN}/sendMessage" 2>&1)
  if [[ "$resp" == *"can't parse entities"* ]]; then   # bad HTML → resend as plain text
    text=$(printf '%s' "$text" | sed -e 's/<[^>]*>//g' -e 's/&lt;/</g; s/&gt;/>/g; s/&amp;/\&/g')
    resp=$(curl -sS --max-time 20 --retry 3 --retry-delay 3 \
            --data-urlencode "chat_id=${TG_CHAT_ID}" --data-urlencode "text=${text}" \
            "https://api.telegram.org/bot${TG_BOT_TOKEN}/sendMessage" 2>&1)
  fi
  if [[ "$resp" != *'"ok":true'* ]]; then
    echo "⚠ Telegram send failed: ${resp:0:300}" >&2
    return 1
  fi
}

if (( TEST_TG )); then
  [[ -z "$TG_BOT_TOKEN" || -z "$TG_CHAT_ID" ]] && { echo "TG_BOT_TOKEN / TG_CHAT_ID not set" >&2; exit 2; }
  tg_send "🔔 <b>[$(html_escape "$TG_NAME")]</b> Maskfish pipeline: Telegram works!" && echo "Sent." || exit 1
  exit 0
fi

[[ "$GEN" =~ ^[0-9]+$ ]] || { echo "Missing or invalid -g/--gen N" >&2; usage >&2; exit 2; }
NEXT=$(( GEN + 1 ))

# ----------------------------------------------------------------------------- file names / architecture
# ARCH_FULL, FEATURE_ARCH, BIN_BASE, MAKE_FLAGS, TRAIN_ARCH, LP, PREP_DIR (see arch.sh)
source "$SCRIPT_DIR/arch.sh"
set_arch_vars || exit 2
ENGINE="${ENGINE:-$SRC_DIR/$BIN_BASE}"
TAGSFX=""; [[ -n "$TAG" ]] && TAGSFX="_${TAG}"
[[ -z "$TAG" || "$TAG" =~ ^[A-Za-z0-9.]+$ ]] || { echo "--tag may only contain letters, digits and dots" >&2; exit 2; }

NET_CUR="nets/${LP}gen${GEN}.nnue"
NET_NEXT="nets/${LP}gen${NEXT}.nnue"
RUN_DIR="runs/${LP}gen${NEXT}"
LOG_DIR="logs/${LP}gen${GEN}${TAGSFX}"
GEN_TXT="data/${LP}gen${GEN}${TAGSFX}.txt"
VAL_TXT="data/${LP}val${GEN}${TAGSFX}.txt"
mkdir -p nets data runs "$LOG_DIR" "$PREP_DIR"

# a different seed for every generation / tag (set SEED_BASE to override)
if [[ -z "$SEED_BASE" ]]; then
  th=0; [[ -n "$TAG" ]] && th=$(( $(printf '%s' "$TAG" | cksum | cut -d' ' -f1) % 9973 ))
  SEED_BASE=$(( (GEN + 1) * 100000 + th * 10 ))
fi
SEED_TRAIN=$(( SEED_BASE + 1 )); SEED_VAL=$(( SEED_BASE + 2 ))

# ----------------------------------------------------------------------------- helpers
NAME_TAG="<b>[$(html_escape "$TG_NAME")]</b> $(html_escape "${LP}gen${GEN}${TAGSFX}")"
T_START=$SECONDS; CUR_STEP=""; CUR_LOG=""; FAILED_SENT=0; DONE=0
declare -a SUMMARY=()

fmt_dur() { local s=$1; printf '%dh%02dm%02ds' $((s/3600)) $((s%3600/60)) $((s%60)); }
fmt_num() { printf "%'d" "$1" 2>/dev/null || printf '%d' "$1"; }
log()  { echo "[$(date '+%F %T')] $*"; }
words() { local -n _arr=$1; read -r -a _arr <<< "${2:-}"; }   # split a config string into an array

kill_tree() {
  local p; for p in $(pgrep -P "$1" 2>/dev/null); do kill_tree "$p"; done
  # a command started by run() leads its own process group: killing the group also
  # catches the pool workers multiprocessing respawns while its workers are killed
  [[ "$(ps -o pgid= -p "$1" 2>/dev/null | tr -d ' ')" == "$1" ]] && kill -TERM -- "-$1" 2>/dev/null
  kill -TERM "$1" 2>/dev/null
}
kill_children() { local p; for p in $(pgrep -P $$ 2>/dev/null); do kill_tree "$p"; done; }
# own process group for every command (if setsid exists), see kill_tree
if command -v setsid >/dev/null 2>&1; then GROUP=(setsid -w); else GROUP=(); fi

notify_fail() {   # $1 = reason
  (( FAILED_SENT )) && return
  FAILED_SENT=1
  local tail_txt=""
  if [[ -n "$CUR_LOG" && -f "$CUR_LOG" ]]; then
    tail_txt=$(tail -n 25 "$CUR_LOG" | cut -c1-200)
  fi
  local msg="❌ ${NAME_TAG} · FAILED at step <b>$(html_escape "${CUR_STEP:-?}")</b>
$(html_escape "$1")
Total time: $(fmt_dur $((SECONDS - T_START)))"
  [[ -n "$tail_txt" ]] && msg+="
<pre>$(html_escape "$tail_txt")</pre>"
  [[ -n "$CUR_LOG" ]] && msg+="
Log: <code>$(html_escape "$TRAINER_DIR/$CUR_LOG")</code>"
  log "FAILED [$CUR_STEP]: $1"
  tg_send "$msg"
}

on_signal() {
  trap - INT TERM
  notify_fail "Stopped by signal $1 (Ctrl+C / kill)"
  kill_children 2>/dev/null
  exit 130
}
on_exit() {
  local rc=$?
  if (( rc != 0 && ! DONE )); then notify_fail "Script exited unexpectedly (exit $rc)"; fi
}
trap 'on_signal INT' INT
trap 'on_signal TERM' TERM
trap on_exit EXIT

# Run one command with logging; returns the command's exit code
run() {   # run LOG cmd...
  local logf="$1"; shift
  log "\$ $*" | tee -a "$logf"
  (( DRY_RUN )) && return 0
  # background + wait: so that Ctrl+C / kill are handled at once (bash defers traps while a foreground command runs)
  # 9>&-: the run lock is not inherited, so a stray process cannot block the next run
  ( "${GROUP[@]}" "$@" 9>&- 2>&1 | tee -a "$logf"; exit "${PIPESTATUS[0]}" ) &
  wait $!
}

# Run one step: step "Title" function  (the function adds lines to the success message with info)
STEP_INFO=""
step() {
  local title="$1" fn="$2"
  CUR_STEP="$title"; CUR_LOG="$LOG_DIR/$(date +%m%d-%H%M%S)-${fn}.log"; STEP_INFO=""
  : > "$CUR_LOG"
  log "════ START: $title  (log: $CUR_LOG)"
  local t0=$SECONDS
  "$fn"; local rc=$?
  local dur; dur=$(fmt_dur $((SECONDS - t0)))
  if (( rc != 0 )); then
    notify_fail "Exit code $rc after $dur"
    exit 1
  fi
  log "════ DONE: $title ($dur)"
  SUMMARY+=("✅ ${title} (${dur})")
  local msg="✅ ${NAME_TAG} · <b>$(html_escape "$title")</b> done (${dur})"
  [[ -n "$STEP_INFO" ]] && msg+="
${STEP_INFO}"
  tg_send "$msg"
  CUR_LOG=""
}
info() { STEP_INFO+="${STEP_INFO:+
}• $*"; }   # add one (escaped) line to the success message

fail() { echo "ERROR: $*" | tee -a "$CUR_LOG" >&2; return 1; }

count_lines() { local n=0 f; for f in "$@"; do [[ -f "$f" ]] && n=$(( n + $(wc -l < "$f") )); done; echo "$n"; }

# ----------------------------------------------------------------------------- steps
s_preflight() {
  command -v "$PYTHON" >/dev/null || fail "Python not found: $PYTHON" || return 1
  command -v curl >/dev/null || echo "Warning: curl not found → no Telegram messages" | tee -a "$CUR_LOG"
  local mods="numpy"
  [[ "$MODE" != "gen" || "$GEN" == 0 ]] && mods+=" zstandard torch"
  run "$CUR_LOG" "$PYTHON" -c "
import importlib, sys
for m in '$mods'.split():
    importlib.import_module(m)
print('python', sys.version.split()[0], 'OK:', '$mods')
" || fail "Missing Python packages — run: $PYTHON -m pip install -r requirements.txt" || return 1
  if [[ "$MODE" != train ]] && (( GEN > 0 )) && [[ ! -f "$NET_CUR" ]]; then
    fail "Current net $NET_CUR not found (copy it into nets/ before generating data)" || return 1
  fi
  autotune
}

gb() { awk -v m="$1" 'BEGIN{printf "%.1f", m/1024}'; }
src() { [[ -n "${USERSET[$1]:-}" ]] && printf ' (config)' || printf ''; }

# Probe CPU / RAM / disk / GPU, then choose the AUTO_VARS parameters the user left empty
autotune() {
  declare -A HW=()
  local probe=() k v
  [[ "$MODE" != gen && -z "${USERSET[BATCH_SIZE]:-}" && "$DEVICE" != cpu ]] && (( ! DRY_RUN )) && probe=(--probe-batch)
  (( ${#probe[@]} && QAT_START > 0 )) && probe+=(--qat)
  local target=$BATCH_TARGET; [[ -n "${USERSET[BATCH_SIZE]:-}" ]] && target=$BATCH_SIZE
  echo "\$ $PYTHON hw_probe.py --arch $ARCH_FULL --batch $target ${probe[*]}" >> "$CUR_LOG"
  while IFS='=' read -r k v; do
    case "$k" in
      HW_CPUS|HW_RAM_TOTAL_MB|HW_RAM_AVAIL_MB|HW_DISK_FREE_MB|HW_CUDA|HW_GPU_COUNT|HW_GPU_INDEX|\
      HW_GPU_TOTAL_MB|HW_GPU_FREE_MB|HW_BATCH_FIT|HW_BATCH_PEAK_MB)
        [[ "$v" =~ ^[0-9]+$ ]] && HW[${k#HW_}]=$v ;;
      HW_GPU_NAME|HW_TORCH) HW[${k#HW_}]=${v//[^A-Za-z0-9_.+-]/} ;;
    esac
    echo "$k=$v" >> "$CUR_LOG"
  done < <("$PYTHON" "$SCRIPT_DIR/hw_probe.py" --arch "$ARCH_FULL" --batch "$target" --path "$TRAINER_DIR" "${probe[@]}" 2>>"$CUR_LOG")

  local cpus=${HW[CPUS]:-$NCPU}
  local ram=${HW[RAM_TOTAL_MB]:-0} avail=${HW[RAM_AVAIL_MB]:-0}
  local disk=${HW[DISK_FREE_MB]:-$(df -Pk . | awk 'NR==2{print int($4/1024)}')}
  (( avail > 0 )) || avail=4096
  NCPU=$cpus

  # RAM per engine (net + hash + python process) and bytes per prepared position
  local eng_mb bpp ck_mb nnue_mb
  case "$NNUE_ARCH" in
    default)     eng_mb=200; bpp=260; ck_mb=190;  nnue_mb=8 ;;
    att)         eng_mb=300; bpp=260; ck_mb=750;  nnue_mb=30 ;;
    threats)     eng_mb=450; bpp=350; ck_mb=1300; nnue_mb=60 ;;
    att-threats) eng_mb=600; bpp=350; ck_mb=1900; nnue_mb=80 ;;
  esac
  (( LAYERS == 2 )) && ck_mb=$(( ck_mb * 11 / 10 ))
  (( META )) && bpp=$(( bpp + 70 ))       # 80 feature columns instead of 64
  local base=$(( cpus > 1 ? cpus - 1 : 1 )) cap
  if [[ -z "${USERSET[GEN_WORKERS]:-}" ]]; then
    cap=$(( avail * 85 / 100 / eng_mb )); GEN_WORKERS=$(( base < cap ? base : cap )); (( GEN_WORKERS < 1 )) && GEN_WORKERS=1
  fi
  if [[ -z "${USERSET[MATCH_WORKERS]:-}" ]]; then   # each worker = 2 engines
    cap=$(( avail * 85 / 100 / (2 * eng_mb) )); MATCH_WORKERS=$(( base < cap ? base : cap )); (( MATCH_WORKERS < 1 )) && MATCH_WORKERS=1
  fi
  if [[ -z "${USERSET[SHARD_SIZE]:-}" ]]; then      # README: RAM ≈ 2 × bpp × shard_size
    SHARD_SIZE=$(( avail * 40 / 100 * 1048576 / (2 * bpp) / 100000 * 100000 ))
    (( SHARD_SIZE > 2000000 )) && SHARD_SIZE=2000000; (( SHARD_SIZE < 100000 )) && SHARD_SIZE=100000
  fi
  if [[ -z "${USERSET[PREP_WORKERS]:-}" ]]; then
    local shard_mb=$(( SHARD_SIZE * 2 * bpp / 1048576 ))
    PREP_WORKERS=$(( (avail - shard_mb) / 250 )); (( PREP_WORKERS > cpus )) && PREP_WORKERS=$cpus; (( PREP_WORKERS < 1 )) && PREP_WORKERS=1
  fi

  # GPU
  local gpu_txt="none"
  if [[ "${HW[CUDA]:-0}" == 1 && -n "${HW[GPU_NAME]:-}" ]]; then
    gpu_txt="${HW[GPU_NAME]//_/ } (#${HW[GPU_INDEX]:-0}) $(gb "${HW[GPU_TOTAL_MB]:-0}") GB, $(gb "${HW[GPU_FREE_MB]:-0}") GB free"
    if (( TRAIN_GPUS > 1 )); then
      gpu_txt+=" · ${HW[GPU_COUNT]:-1} GPUs, training on ${TRAIN_GPUS} (DDP)"
    elif (( ${HW[GPU_COUNT]:-1} > 1 )); then
      gpu_txt+=" · ${HW[GPU_COUNT]} GPUs, using the one with the most free memory"
    fi
    if (( ${HW[GPU_COUNT]:-1} > 1 && TRAIN_GPUS <= 1 )) && [[ -z "${CUDA_VISIBLE_DEVICES:-}" ]]; then
      export CUDA_VISIBLE_DEVICES=${HW[GPU_INDEX]:-0}
    fi
    if (( ${HW[GPU_FREE_MB]:-0} * 10 < ${HW[GPU_TOTAL_MB]:-0} * 7 )); then
      info "⚠ Other processes are using $(gb $(( ${HW[GPU_TOTAL_MB]} - ${HW[GPU_FREE_MB]} ))) GB of the GPU"
    fi
  fi
  if [[ "$MODE" != gen ]]; then
    if [[ "${HW[CUDA]:-0}" != 1 && "$DEVICE" != cpu ]]; then
      if [[ "$REQUIRE_GPU" == 1 ]]; then
        fail "No CUDA. Install a CUDA build of torch, or set REQUIRE_GPU=0 / DEVICE=cpu to train on the CPU (very slow)" || return 1
      fi
      DEVICE=cpu
    fi
    local batch_txt
    if [[ -n "${USERSET[BATCH_SIZE]:-}" ]]; then
      batch_txt="$BATCH_SIZE (config)"
    elif [[ "$DEVICE" == cpu ]]; then
      BATCH_SIZE=$BATCH_TARGET; batch_txt="$BATCH_SIZE (CPU)"
    elif [[ -n "${HW[BATCH_FIT]:-}" ]]; then
      (( ${HW[BATCH_FIT]} > 0 )) || fail "Not enough GPU memory to train, even with batch 1024" || return 1
      BATCH_SIZE=${HW[BATCH_FIT]}
      batch_txt="$BATCH_SIZE (trial run on the GPU, peak $(gb "${HW[BATCH_PEAK_MB]:-0}") GB)"
      (( BATCH_SIZE < BATCH_TARGET )) && batch_txt+=" ⚠ below the default $BATCH_TARGET: not enough VRAM"
    else
      BATCH_SIZE=$BATCH_TARGET; batch_txt="$BATCH_SIZE (could not measure)"
    fi
    if [[ -z "${USERSET[TRAIN_THREADS]:-}" ]]; then
      if [[ "$DEVICE" == cpu ]]; then TRAIN_THREADS=$cpus; else TRAIN_THREADS=0; fi
    fi
    if (( TRAIN_GPUS > 1 )); then
      [[ "$DEVICE" != cpu ]] || fail "TRAIN_GPUS=$TRAIN_GPUS needs CUDA (DEVICE=cpu is set)" || return 1
      (( TRAIN_GPUS <= ${HW[GPU_COUNT]:-0} )) || fail "TRAIN_GPUS=$TRAIN_GPUS but only ${HW[GPU_COUNT]:-0} GPU(s) found" || return 1
      # BATCH_SIZE is the global batch (train.py splits it between the GPUs)
      BATCH_SIZE=$(( BATCH_SIZE / TRAIN_GPUS * TRAIN_GPUS ))
      batch_txt+=" · ${TRAIN_GPUS} GPUs × $(( BATCH_SIZE / TRAIN_GPUS ))"
    fi

    # Disk: data (if generated) + one .nnue per epoch + checkpoints → pick a CHECKPOINT_EVERY that fits
    local pos=0; [[ "$MODE" == full ]] && pos=$(( (GAMES + VAL_GAMES) * 80 ))
    local data_mb=$(( pos * (100 + bpp) / 1048576 ))
    local budget=$(( (disk - data_mb) / 2 - EPOCHS * nnue_mb - ck_mb ))   # use at most ~half of the remaining disk
    if [[ -z "${USERSET[CHECKPOINT_EVERY]:-}" ]]; then
      local ce n
      CHECKPOINT_EVERY=""
      for ce in 1 2 5 10 20 "$EPOCHS"; do
        n=$(( (EPOCHS + ce - 1) / ce ))
        if (( n * ck_mb <= budget )); then CHECKPOINT_EVERY=$ce; break; fi
      done
      [[ -n "$CHECKPOINT_EVERY" ]] || fail "Not enough disk: need ~$(gb $(( data_mb + EPOCHS * nnue_mb + 3 * ck_mb ))) GB, $(gb "$disk") GB free" || return 1
    fi
    info "Train: device ${DEVICE:-cuda} · batch ${batch_txt} · checkpoint every ${CHECKPOINT_EVERY} epoch(s)$(src CHECKPOINT_EVERY) (~$(gb "$ck_mb") GB each)$( (( TRAIN_THREADS > 0 )) && printf ' · %s CPU threads' "$TRAIN_THREADS")"
  else
    local pos=$(( (GAMES + VAL_GAMES) * 80 )) need
    need=$(( pos * 100 / 1048576 )); (( NO_PREPARE )) || need=$(( pos * (100 + bpp) / 1048576 ))
    (( need < disk )) || fail "Not enough disk for the data: need ~$(gb "$need") GB, $(gb "$disk") GB free" || return 1
  fi

  info "Machine: ${cpus} CPUs · RAM $(gb "$ram") GB ($(gb "$avail") free) · disk $(gb "$disk") GB free"
  info "GPU: $(html_escape "$gpu_txt")${HW[TORCH]:+ · torch ${HW[TORCH]}}"
  if [[ "$MODE" != train ]]; then
    info "Data generation: ${GEN_WORKERS} worker$(src GEN_WORKERS) · prepare: ${PREP_WORKERS} worker$(src PREP_WORKERS), shard $(fmt_num "$SHARD_SIZE")$(src SHARD_SIZE)"
  else
    info "Prepare (if needed): ${PREP_WORKERS} worker$(src PREP_WORKERS), shard $(fmt_num "$SHARD_SIZE")$(src SHARD_SIZE)"
  fi
  [[ "$MODE" != gen ]] && (( ! SKIP_MATCH )) && info "SPRT: ${MATCH_WORKERS} worker$(src MATCH_WORKERS)"
  local line; for line in "GEN_WORKERS=$GEN_WORKERS" "MATCH_WORKERS=$MATCH_WORKERS" "PREP_WORKERS=$PREP_WORKERS" \
      "SHARD_SIZE=$SHARD_SIZE" "BATCH_SIZE=$BATCH_SIZE" "CHECKPOINT_EVERY=$CHECKPOINT_EVERY" "TRAIN_THREADS=$TRAIN_THREADS" "DEVICE=$DEVICE" "TRAIN_GPUS=$TRAIN_GPUS"; do
    echo "chosen: $line" >> "$CUR_LOG"
  done
  return 0
}

s_build() {
  if [[ -x "$ENGINE" && $REBUILD == 0 ]]; then
    echo "Engine already built: $ENGINE (use --rebuild to rebuild)" | tee -a "$CUR_LOG"
    info "Using existing engine: $(html_escape "$ENGINE")"
    return 0
  fi
  command -v make >/dev/null || fail "make not found" || return 1
  local keep=""
  # make clean deletes src/maskfish — keep the default binary when building another architecture
  if [[ "$BIN_BASE" != maskfish && -x "$SRC_DIR/maskfish" ]]; then
    keep="$SRC_DIR/maskfish.keep.$$"; cp -p "$SRC_DIR/maskfish" "$keep"
  fi
  run "$CUR_LOG" make -C "$SRC_DIR" clean || return 1
  run "$CUR_LOG" make -C "$SRC_DIR" -j"$NCPU" build ARCH="$MAKE_ARCH" "${MAKE_FLAGS[@]}" || return 1
  if [[ "$BIN_BASE" != maskfish ]] && (( ! DRY_RUN )); then
    mv -f "$SRC_DIR/maskfish" "$ENGINE" || return 1
    [[ -n "$keep" ]] && mv -f "$keep" "$SRC_DIR/maskfish"
  fi
  (( DRY_RUN )) || [[ -x "$ENGINE" ]] || fail "Build finished but $ENGINE is missing" || return 1
  info "Engine: $(html_escape "$ENGINE") (ARCH=$(html_escape "$MAKE_ARCH") ${MAKE_FLAGS[*]})"
}

s_check() {
  run "$CUR_LOG" "$PYTHON" -u verify.py --engine "$ENGINE" --arch "$ARCH_FULL" "${EVAL_ARG[@]}" \
    || fail "Engine and trainer are NOT bit-exact → do not train (see README section 11)" || return 1
  info "$(html_escape "$(grep -h 'bit-exact' "$CUR_LOG" | tail -1)")"
}

s_init() {
  if [[ -f "$NET_CUR" ]]; then
    echo "$NET_CUR exists" | tee -a "$CUR_LOG"; info "$(html_escape "$NET_CUR") exists, skipped"; return 0
  fi
  if [[ -n "$INIT_NET" ]]; then
    # an existing net (e.g. of the default line) converted into this architecture
    # (README section 7.9): -meta / -ctx keep its evaluation, -blend its layer
    # stacks, -q2 (from a quant=1 net) requantizes it (README 7.12)
    [[ -f "$INIT_NET" ]] || (( DRY_RUN )) || fail "INIT_NET $INIT_NET not found" || return 1
    run "$CUR_LOG" "$PYTHON" -u serialize.py --convert "$ARCH_FULL" "$INIT_NET" "$NET_CUR" \
      || fail "INIT_NET cannot be converted into $ARCH_FULL (README section 7.9)" || return 1
    info "Created $(html_escape "$NET_CUR") from $(html_escape "$INIT_NET")"
    return 0
  fi
  if (( ! PSQT )); then
    fail "A material-only net needs PSQT: set INIT_NET, or train a first $ARCH_FULL net with train.py --init-net (README section 7.9)"
    return 1
  fi
  run "$CUR_LOG" "$PYTHON" -u init_net.py "$NET_CUR" --arch "$ARCH_FULL" || return 1
  info "Created material-only net: $(html_escape "$NET_CUR")"
}

# collect the .partK files left by an interrupted run (they hold finished games only)
salvage_parts() {
  local out="$1" parts=("$1".part*)
  [[ -e "${parts[0]}" ]] || return 0
  local dst; dst="${out}.salvage-$(date +%Y%m%d-%H%M%S)"
  cat "${parts[@]}" > "$dst" && rm -f "${parts[@]}"
  echo "Collected $(count_lines "$dst") positions from old .part files → $dst" | tee -a "$CUR_LOG"
  info "Recovered $(fmt_num "$(count_lines "$dst")") positions from an interrupted run → $(html_escape "$dst")"
}

gen_common() {   # $1 = output file, $2 = number of games, $3 = seed
  local out="$1" games="$2" seed="$3"
  if [[ -s "$out" && $FORCE == 0 ]]; then
    echo "$out exists ($(count_lines "$out") lines), skipped (use --force to regenerate)" | tee -a "$CUR_LOG"
    info "$(html_escape "$out") exists ($(fmt_num "$(count_lines "$out")") positions), skipped"
    return 0
  fi
  [[ -f "$NET_CUR" ]] || (( DRY_RUN )) || fail "Current net $NET_CUR not found" || return 1
  salvage_parts "$out"
  local cmd=("$PYTHON" -u gen_data.py --engine "$ENGINE" --net "$NET_CUR"
             --games "$games" --nodes "$NODES" --workers "$GEN_WORKERS"
             --adjudicate "$ADJUDICATE" --seed "$seed" --out "$out")
  (( DEPTH > 0 )) && cmd+=(--depth "$DEPTH")
  local opts; words opts "$GEN_OPTS"; opts+=("${EVAL_OPT[@]}")
  [[ -n "$CHANCE_SCALING" ]] && opts+=("ChanceScaling=$CHANCE_SCALING")
  (( ${#opts[@]} )) && cmd+=(--opt "${opts[@]}")
  run "$CUR_LOG" "${cmd[@]}" || return 1
  (( DRY_RUN )) && return 0
  local n; n=$(count_lines "$out")
  (( n > 0 )) || fail "gen_data finished but $out is empty" || return 1
  info "$(fmt_num "$n") positions from $(fmt_num "$games") games → $(html_escape "$out") ($(du -h "$out" | cut -f1))"
}

s_gendata() { gen_common "$GEN_TXT" "$GAMES" "$SEED_TRAIN"; }
s_genval()  { gen_common "$VAL_TXT" "$VAL_GAMES" "$SEED_VAL"; }

s_fit() {   # informational only, never fails the pipeline
  [[ -s "$GEN_TXT" ]] || (( DRY_RUN )) || { info "No $GEN_TXT to fit"; return 0; }
  if run "$CUR_LOG" "$PYTHON" -u fit_scaling.py "$GEN_TXT"; then
    local line; line=$(grep -h 'fitted scale' "$CUR_LOG" | tail -1)
    [[ -n "$line" ]] && info "$(html_escape "$line")"
    info "Using SCALING=${SCALING}${CHANCE_SCALING:+, ChanceScaling=$CHANCE_SCALING} (change it in scripts/pipeline.env if needed)"
  else
    info "⚠ fit_scaling failed (ignored, training is not affected)"
  fi
  return 0
}

# prepare one text file → one prefix; $3=1 forces a redo
prepare_one() {   # $1 = main text file, $2 = output prefix, $3 = force
  local txt="$1" prefix="$2" force="$3"
  # ".material" is written since the shards hold material / rule40 (evaluate() scaling in the loss)
  if [[ -f "${prefix}.arch" && "$(cat "${prefix}.arch")" != "$FEATURE_ARCH" ]]; then
    echo "Prepared for $(cat "${prefix}.arch"), not $FEATURE_ARCH: preparing again" | tee -a "$CUR_LOG"
    force=1
  fi
  if [[ "$EVAL_SCALING" == Alignment && -f "${prefix}.arch" ]] \
     && ! grep -qw allmat "${prefix}.fields" 2>/dev/null; then
    echo "Prepared without se / allmat (needed by EVAL_SCALING=Alignment): preparing again" | tee -a "$CUR_LOG"
    force=1
  fi
  if [[ -f "${prefix}.arch" && -f "${prefix}.material" && "$force" == 0 ]]; then
    echo "Already prepared: $prefix" | tee -a "$CUR_LOG"; return 0
  fi
  if [[ -f "${prefix}.arch" && ! -f "${prefix}.material" ]]; then
    echo "Prepared by an older prepare_data.py (no material / rule40): preparing again" | tee -a "$CUR_LOG"
    force=1
  fi
  if [[ "$force" == 1 ]] && (( ! DRY_RUN )); then
    rm -f "${prefix}".arch "${prefix}".material "${prefix}".fields "${prefix}"-[0-9][0-9][0-9][0-9][0-9].*.npy
  fi
  local inputs=("$txt") s
  for s in "${txt}".salvage-*; do [[ -s "$s" ]] && inputs+=("$s"); done
  local cmd=("$PYTHON" -u prepare_data.py "${inputs[@]}" --out "$prefix" --arch "$FEATURE_ARCH"
             --shard-size "$SHARD_SIZE" --max-score "$MAX_SCORE" --score-scale "$SCORE_SCALE")
  [[ -n "$PREP_WORKERS" ]] && cmd+=(--workers "$PREP_WORKERS")
  # data generated with JieqiMaterial=true: evaluate() uses jieqi_major_material()
  [[ " $GEN_OPTS " =~ [[:space:]]JieqiMaterial=(true|1)[[:space:]] ]] && cmd+=(--jieqi-material)
  run "$CUR_LOG" "${cmd[@]}" || return 1
  (( DRY_RUN )) && return 0
  [[ -f "${prefix}.arch" ]] || fail "prepare finished but ${prefix}.arch is missing" || return 1
  local res; res=$(grep -h 'shard(s) ->' "$CUR_LOG" | tail -1)
  info "$(html_escape "$(basename "$prefix")"): $(html_escape "${res%% -> *}")"
}

# prepare every text file of generations TRAIN_FROM..N not prepared yet (including files copied from other machines)
s_prepare() {
  local k kind txt base tag prefix f did=0
  for (( k = TRAIN_FROM; k <= GEN; k++ )); do
    for kind in gen val; do
      (( k < GEN )) && [[ "$kind" == val ]] && continue      # only the current generation's validation set is needed
      for txt in "data/${LP}${kind}${k}.txt" "data/${LP}${kind}${k}"_*.txt; do
        [[ -s "$txt" ]] || continue
        base=$(basename "$txt" .txt); tag="${base#"${LP}${kind}${k}"}"   # "" or "_TAG"
        [[ "$kind" == gen ]] && prefix="$PREP_DIR/${LP}train${k}${tag}" || prefix="$PREP_DIR/${LP}val${k}${tag}"
        f=0; (( FORCE )) && (( k == GEN )) && [[ "$tag" == "$TAGSFX" ]] && f=1
        prepare_one "$txt" "$prefix" "$f" || return 1
        did=1
      done
    done
  done
  if (( DRY_RUN && ! did )); then
    prepare_one "$GEN_TXT" "$PREP_DIR/${LP}train${GEN}${TAGSFX}" 0
    prepare_one "$VAL_TXT" "$PREP_DIR/${LP}val${GEN}${TAGSFX}" 0
    return 0
  fi
  (( did )) || fail "No text file to prepare (data/${LP}gen${GEN}*.txt)" || return 1
  return 0
}

collect_prefixes() {   # $1 = train|val → prints the prepared prefixes
  local kind="$1" k a from=$TRAIN_FROM
  [[ "$kind" == val ]] && from=$GEN
  for (( k = from; k <= GEN; k++ )); do
    for a in "$PREP_DIR/${LP}${kind}${k}.arch" "$PREP_DIR/${LP}${kind}${k}"_*.arch; do
      [[ -f "$a" ]] && echo "${a%.arch}"
    done
  done
}

last_epoch() {   # highest epoch with a .nnue in RUN_DIR
  local f e max=0
  for f in "$RUN_DIR"/epoch_*.nnue; do
    [[ -f "$f" ]] || continue
    e=${f##*/epoch_}; e=${e%.nnue}
    [[ "$e" =~ ^[0-9]+$ ]] && (( e > max )) && max=$e
  done
  echo "$max"
}

s_train() {
  local done_ep; done_ep=$(last_epoch)
  if (( done_ep >= EPOCHS )); then
    echo "$RUN_DIR already has epoch_${done_ep}.nnue ≥ EPOCHS=$EPOCHS, skipping training" | tee -a "$CUR_LOG"
    info "Already trained (epoch ${done_ep}), skipped"
    return 0
  fi
  local train=() val=() extra
  mapfile -t train < <(collect_prefixes train)
  mapfile -t val < <(collect_prefixes val)
  words extra "$EXTRA_TRAIN"; train+=("${extra[@]}")
  (( ${#train[@]} )) || (( DRY_RUN )) || fail "No prepared data in $PREP_DIR (run --gen-only first)" || return 1
  local cmd=("$PYTHON" -u train.py "${train[@]}")
  if (( TRAIN_GPUS > 1 )); then   # one process per GPU (train.py: Distributed)
    cmd=(env PYTHONUNBUFFERED=1 "$PYTHON" -m torch.distributed.run --standalone
         --nproc_per_node "$TRAIN_GPUS" train.py "${train[@]}")
  fi
  if (( ${#val[@]} )); then cmd+=(--val "${val[@]}"); else
    echo "Warning: no validation set" | tee -a "$CUR_LOG"; info "⚠ No validation set"; fi
  cmd+=(--out "$RUN_DIR" --epochs "$EPOCHS" --epoch-size "$EPOCH_SIZE" --batch-size "$BATCH_SIZE"
        --lr "$LR" --gamma "$GAMMA" --lambda "$LAMBDA" --scaling "$SCALING"
        "${TRAIN_ARCH[@]}" --checkpoint-every "$CHECKPOINT_EVERY")
  [[ -n "$DEVICE" ]] && cmd+=(--device "$DEVICE")
  (( TRAIN_THREADS > 0 )) && cmd+=(--threads "$TRAIN_THREADS")
  (( QAT_START > 0 )) && cmd+=(--qat-start "$QAT_START")
  cmd+=("${EVAL_ARG[@]}")
  if [[ -f "$RUN_DIR/last.pt" && $NO_RESUME == 0 ]]; then
    cmd+=(--resume "$RUN_DIR/last.pt"); info "Resuming from $(html_escape "$RUN_DIR/last.pt") (epoch ${done_ep})"
  elif (( GEN > 0 )) || [[ -n "$INIT_NET" ]] && [[ "$INIT_FROM_CURRENT" == 1 ]]; then
    # (gen0 made from INIT_NET is a trained net: continue from it too)
    [[ -f "$NET_CUR" ]] || (( DRY_RUN )) || fail "$NET_CUR not found for --init-net" || return 1
    cmd+=(--init-net "$NET_CUR")
  fi
  local targs; words targs "$TRAIN_ARGS"; cmd+=("${targs[@]}")
  mkdir -p "$RUN_DIR"
  log "\$ ${cmd[*]}" | tee -a "$CUR_LOG"
  (( DRY_RUN )) && return 0

  # run in the background and watch the log: Telegram every TG_EPOCH_EVERY epochs, stop at once if the loss is nan
  "${cmd[@]}" >> "$CUR_LOG" 2>&1 9>&- &
  local pid=$! nanflag="$LOG_DIR/.nan.$$"
  rm -f "$nanflag"
  tail -n +1 -f --pid="$pid" "$CUR_LOG" 2>/dev/null | while IFS= read -r line; do
    printf '%s\n' "$line"
    if [[ "$line" =~ loss\ [-+]?(nan|inf) ]]; then
      : > "$nanflag"; kill_tree "$pid"
    elif [[ "$line" =~ ^epoch\ ([0-9]+):\ train\ loss ]]; then
      local ep=${BASH_REMATCH[1]}
      if (( TG_EPOCH_EVERY > 0 && ep % TG_EPOCH_EVERY == 0 && ep < EPOCHS )); then
        tg_send "📈 ${NAME_TAG} · train $(html_escape "$line") (/${EPOCHS})" >/dev/null 2>&1
      fi
    fi
  done &
  local mon=$!
  wait "$pid"; local rc=$?
  wait "$mon" 2>/dev/null
  if [[ -f "$nanflag" ]]; then rm -f "$nanflag"; fail "Loss = NaN/Inf → training stopped. Try a lower LR or MAX_SCORE"; return 1; fi
  (( rc == 0 )) || return "$rc"
  [[ -f "$RUN_DIR/epoch_${EPOCHS}.nnue" ]] || fail "Training finished but $RUN_DIR/epoch_${EPOCHS}.nnue is missing" || return 1
  local lastl best
  lastl=$(grep -hE '^epoch [0-9]+: train loss' "$CUR_LOG" | tail -1)
  best=$(grep -hE '^epoch [0-9]+: .*val loss' "$CUR_LOG" \
         | awk '{v=$0; sub(/.*val loss /,"",v); sub(/,.*/,"",v); e=$2; sub(":","",e)
                 if (b=="" || v+0<b+0) {b=v; be=e}} END{if(b!="") print "epoch " be " (val " b ")"}')
  info "$(html_escape "$lastl")"
  [[ -n "$best" ]] && info "Best val loss: $(html_escape "$best")"
  info "Output: $(html_escape "$RUN_DIR")/epoch_${EPOCHS}.nnue"
}

candidates() {
  local e
  for e in $MATCH_EPOCHS; do [[ "$e" == last ]] && echo "$EPOCHS" || echo "$e"; done
}

s_verify() {
  local e net ck ok=0
  for e in $(candidates); do
    net="$RUN_DIR/epoch_${e}.nnue"; ck="$RUN_DIR/epoch_${e}.pt"
    [[ -f "$net" ]] || (( DRY_RUN )) || fail "$net not found" || return 1
    local cmd=("$PYTHON" -u verify.py --engine "$ENGINE" --net "$net" "${EVAL_ARG[@]}")
    [[ -f "$ck" ]] && cmd+=(--checkpoint "$ck")
    run "$CUR_LOG" "${cmd[@]}" || fail "epoch_${e}.nnue is NOT bit-exact with the engine" || return 1
    info "epoch_${e}: $(html_escape "$(grep -h 'bit-exact\|largest' "$CUR_LOG" | tail -2 | tr '\n' ' ')")"
    ok=1
  done
  (( ok )) || (( DRY_RUN )) || fail "MATCH_EPOCHS is empty" || return 1
}

MATCH_RESULT=""
s_match() {
  [[ -f "$NET_CUR" ]] || (( DRY_RUN )) || fail "Reference net $NET_CUR not found" || return 1
  local e net res mopts sprt
  words mopts "$MATCH_OPTS"; [[ -n "$CHANCE_SCALING" ]] && mopts+=("ChanceScaling=$CHANCE_SCALING")
  mopts+=("${EVAL_OPT[@]}")
  words sprt "$SPRT"
  for e in $(candidates); do
    net="$RUN_DIR/epoch_${e}.nnue"
    local cmd=("$PYTHON" -u match.py --engine "$ENGINE" --net-a "$net" --net-b "$NET_CUR"
               --workers "$MATCH_WORKERS")
    if (( MATCH_MOVETIME > 0 )); then cmd+=(--movetime "$MATCH_MOVETIME"); else cmd+=(--nodes "$MATCH_NODES"); fi
    (( ${#sprt[@]} == 2 )) && cmd+=(--sprt "${sprt[@]}")
    (( ${#mopts[@]} )) && cmd+=(--opt-a "${mopts[@]}" --opt-b "${mopts[@]}")
    local mark; mark=$(wc -l < "$CUR_LOG")
    run "$CUR_LOG" "${cmd[@]}" || return 1
    (( DRY_RUN )) && return 0
    res=$(tail -n +"$((mark + 1))" "$CUR_LOG" | grep -hE '^(H1|H0|no decision)' | tail -1)
    local stat; stat=$(tail -n +"$((mark + 1))" "$CUR_LOG" | grep -h '^pairs ' | tail -1)
    grep -q '^interrupted' <(tail -n +"$((mark + 1))" "$CUR_LOG") && { fail "match was interrupted"; return 1; }
    info "epoch_${e} vs $(html_escape "$NET_CUR"): <b>$(html_escape "${res:-?}")</b>"
    [[ -n "$stat" ]] && info "<code>$(html_escape "$stat")</code>"
    if [[ "$res" == H1* ]]; then MATCH_RESULT="$net"; break; fi
  done
  return 0
}

s_promote() {
  if [[ -z "$MATCH_RESULT" ]]; then
    info "⚠ No epoch won the SPRT → keeping $(html_escape "$NET_CUR"). Try more data / another epoch / tune LR, LAMBDA"
    return 0
  fi
  if [[ "$AUTO_PROMOTE" != 1 ]]; then
    info "AUTO_PROMOTE=0: copy it by hand: cp $(html_escape "$MATCH_RESULT") $(html_escape "$NET_NEXT")"; return 0
  fi
  if [[ -e "$NET_NEXT" ]]; then
    info "⚠ $(html_escape "$NET_NEXT") already exists, NOT overwritten. Winning net: $(html_escape "$MATCH_RESULT")"; return 0
  fi
  run "$CUR_LOG" cp "$MATCH_RESULT" "$NET_NEXT" || return 1
  info "🏆 New net: <b>$(html_escape "$NET_NEXT")</b> ← $(html_escape "$MATCH_RESULT")"
  if [[ "$FTPERM" == 1 ]]; then
    # Faster engine, same evaluations (ftperm.py checks it); never fails the pipeline
    local data=() f
    for f in "data/${LP}gen${GEN}".txt{,.zst,.gz} "data/${LP}gen${GEN}"_*.txt{,.zst,.gz}; do
      [[ -f "$f" ]] && data+=("$f")
    done
    if (( ${#data[@]} == 0 )); then
      info "⚠ FTPERM: no text data of generation ${GEN} found, $(html_escape "$NET_NEXT") not reordered"
    elif run "$CUR_LOG" "$PYTHON" -u ftperm.py "$NET_NEXT" "$NET_NEXT" --data "${data[@]}"; then
      info "⚡ $(html_escape "$(grep -h 'all-zero chunks' "$CUR_LOG" | tail -1)")"
    else
      info "⚠ ftperm.py failed (see the log): $(html_escape "$NET_NEXT") kept as trained"
    fi
  fi
  info "Next generation: scripts/pipeline.sh -g ${NEXT}"
}

# ----------------------------------------------------------------------------- lock against concurrent runs
LOCK="$LOG_DIR/.lock"
if command -v flock >/dev/null && (( ! DRY_RUN )); then
  exec 9>"$LOCK"
  flock -n 9 || { echo "Another pipeline is already running for ${LP}gen${GEN}${TAGSFX} (lock $LOCK)" >&2; DONE=1; exit 3; }
fi

# ----------------------------------------------------------------------------- run
case "$MODE" in
  full)  MODE_TXT="full (data → train → SPRT)" ;;
  gen)   MODE_TXT="DATA GENERATION ONLY" ;;
  train) MODE_TXT="TRAINING ONLY" ;;
esac
tg_send "🚀 ${NAME_TAG} · Pipeline started: <b>${MODE_TXT}</b>
net: $(html_escape "$NET_CUR") · arch: $(html_escape "$ARCH_FULL")$( [[ $MODE != train ]] && printf '\ndata: %s games + %s val, %s nodes, seed %s' "$GAMES" "$VAL_GAMES" "$NODES" "$SEED_BASE")$( [[ $MODE != gen ]] && printf '\ntrain: %s epoch × %s, lr %s, λ %s, scaling %s → %s' "$EPOCHS" "$EPOCH_SIZE" "$LR" "$LAMBDA" "$SCALING" "$(html_escape "$RUN_DIR")")"

step "Environment check" s_preflight
step "Build engine" s_build

if [[ "$MODE" != gen ]] && (( ! SKIP_CHECK )); then
  step "Engine/trainer bit-exact check" s_check
fi

if [[ "$MODE" != train ]]; then
  (( GEN == 0 )) && step "Create gen0 net$( [[ -n "$INIT_NET" ]] && echo " (from INIT_NET)" || echo " (material)" )" s_init
  step "Generate training data" s_gendata
  step "Generate validation data" s_genval
  step "Fit scaling (informational)" s_fit
  if ! { [[ "$MODE" == gen ]] && (( NO_PREPARE )); }; then
    step "Prepare data" s_prepare
  fi
else
  # training only: prepare the text files not prepared yet (e.g. data copied from other machines)
  missing=0
  for (( k = TRAIN_FROM; k <= GEN; k++ )); do
    for txt in data/${LP}gen${k}.txt data/${LP}gen${k}_*.txt data/${LP}val${GEN}.txt data/${LP}val${GEN}_*.txt; do
      [[ -s "$txt" ]] || continue
      b=$(basename "$txt" .txt); b="${b/#${LP}gen/${LP}train}"
      [[ -f "$PREP_DIR/$b.arch" && -f "$PREP_DIR/$b.material" ]] || missing=1
    done
  done
  (( missing )) && step "Prepare missing data" s_prepare
fi

if [[ "$MODE" != gen ]]; then
  step "Train ${RUN_DIR}" s_train
  step "Verify trained net" s_verify
  if (( ! SKIP_MATCH )); then
    step "SPRT match" s_match
    step "Promote" s_promote
  fi
fi

DONE=1
final="🎉 ${NAME_TAG} · <b>FINISHED</b> ${MODE_TXT} in $(fmt_dur $((SECONDS - T_START)))"
for l in "${SUMMARY[@]}"; do final+="
$(html_escape "$l")"; done
[[ "$MODE" == gen ]] && final+="
Next: scripts/pipeline.sh -g ${GEN} --train-only"
tg_send "$final"
log "FINISHED ($(fmt_dur $((SECONDS - T_START))))"
